function nameOf(o){return tr(o.name,o.en)}function deptName(id){const d=departments.find(d=>d.id===id);return d?nameOf(d):'—'}function memberName(id){const m=members.find(m=>m.id===Number(id));return m?nameOf(m):'—'}function lab(id){return tx(...(labels[id]||[id,id]))}function duration(n){return `${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`}function date(s){return s.split('-').reverse().join('/')}
function badge(s){const m={active:['فعّال إدارياً','Administratively active'],disabled:['موقوف','Disabled'],draft:['مسودة','Draft'],unverified:['غير متحقق','Not verified'],unconnected:['غير مربوط','Not connected'],pending:['بانتظار المراجعة','Pending review'],paid:['مدفوعة','Paid'],unpaid:['غير مدفوعة','Unpaid'],answered:['تم الرد','Answered'],missed:['لم يتم الرد','Unanswered']};const cls={disabled:'suspended',unverified:'draft',unconnected:'draft',answered:'active',missed:'expired'};return `<span class="status ${cls[s]||s}">${tx(...(m[s]||[s,s]))}</span>`}
function btn(a,b,action,id='',kind='secondary',ic=''){return `<button class="btn-${kind}" data-action="${action}" data-id="${esc(id)}">${ic?icon(ic):''}${tx(a,b)}</button>`}function head(a,b,subA,subB,actions=''){return `<div class="page-head"><div><h1>${tx(a,b)}</h1><p>${tx(subA,subB)}</p></div><div class="head-actions">${actions}</div></div>`}function cardHead(a,b,subA='',subB='',extra=''){return `<div class="card-head"><div><h2>${tx(a,b)}</h2>${subA?`<p>${tx(subA,subB)}</p>`:''}</div>${extra}</div>`}function stats(a,b,value,noteA,noteB,ic,color=''){return `<div class="stat"><div class="stat-top"><span>${tx(a,b)}</span><span class="stat-icon">${icon(ic)}</span></div><strong>${esc(value)}</strong><small class="${color}">${tx(noteA,noteB)}</small></div>`}function info(a,b,v){return `<div class="detail-line"><dt>${tx(a,b)}</dt><dd>${v}</dd></div>`}function sectionNote(a,b){return `<div class="section-note">${tx(a,b)}</div>`}function empty(a,b,subA,subB,ic='info'){return `<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${tx(a,b)}</h3><p>${tx(subA,subB)}</p></div>`}
function field(a,b,name,value='',type='text',required=false,wide=false){return `<div class="form-field ${wide?'full':''}"><label for="f-${name}">${tx(a,b)}${required?' <span class="required">*</span>':''}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="1"':''}></div>`}function select(a,b,name,options,value){return `<div class="form-field"><label for="f-${name}">${tx(a,b)}</label><select id="f-${name}" name="${name}">${options.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('')}</select></div>`}function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${Array.isArray(h)?tx(...h):lab(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td class="empty-row" colspan="${headers.length}">${tx('لا توجد نتائج','No results')}</td></tr>`}</tbody></table></div>`}
function toast(a,b){clearTimeout(toastTimer);$('#toast').textContent=tr(a,b);$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}function previewSaved(){toast('تم حفظ التعديل في المعاينة فقط.','Changes saved in preview only.')}function audit(a,b){activities.unshift({ar:a,en:b,date:new Date().toLocaleString('en-GB',{timeZone:'Asia/Baghdad'})})}
function modal(a,b,body,submitA,submitB,handler){$('#modalTitle').textContent=tr(a,b);$('#modalBody').innerHTML=body;$('#modalSubmit').textContent=tr(submitA,submitB);modalHandler=handler;$('#modal').showModal()}
function renderNav(){names.company=[org.name,org.en];$$('[data-t]').forEach(e=>e.textContent=tr(...names[e.dataset.t]));$('#language').textContent=lang==='ar'?'English':'العربية';$('#tenantLock').innerHTML=icon('shield');$('#bell').innerHTML=icon('bell');$('#demoIcon').innerHTML=icon('info');$('#nav').innerHTML=navItems.map(([id,a,b,ic],i)=>`${i===10?'<div class="nav-divider"></div>':''}<button class="nav-item ${page===id?'active':''}" data-page="${id}">${icon(ic)}<span>${tx(a,b)}</span>${id==='team'?`<span class="nav-count">${members.length}</span>`:''}</button>`).join('')+`<a class="nav-item" href="crm.html">${icon('users')}<span>${tx('إدارة العملاء CRM','Customer management CRM')}</span><span class="nav-count">${VodnoxCRMStore.enabled('VX-1001')?'CRM':'🔒'}</span></a><a class="nav-item" href="forms.html">${icon('plans')}<span>VODNOX FORMS</span><span class="nav-count">${VodnoxFormsStore.enabled('VX-1001')?'FORMS':'🔒'}</span></a>`}
function overview(){const answered=logs.filter(c=>c.status==='answered').length;return head('نظرة عامة','Overview','إدارة فريقك واتصالات مؤسستك من مكان واحد.','Your team and organization communications, in one workspace.',btn('إضافة موظف','Add employee','member','','primary','plus'))+`<section class="welcome"><div><small>VODNOX / YOUR ORGANIZATION</small><h2>${tx('فريق واحد. تواصل أقرب.','One team. Closer connections.')}</h2><p>${tx('أهلاً بك في مساحة','Welcome to')} ${esc(nameOf(org))}</p><div class="tenant-health"><i></i>${tx('حالة الاتصال الفعلية: غير مربوط','Live telephony status: not connected')}</div></div><div class="welcome-end"><b>VX-1001</b><span>${tx('اشتراك أعمال · 01/11/2026','Business subscription · 01/11/2026')}</span></div></section><div class="stats">${stats('الموظفون','Employees',members.length,'حسابات داخل المؤسسة','Organization accounts','users')}${stats('التحويلات','Extensions',extensions.length,'تسجيل SIP غير متحقق','SIP registration unverified','phone')}${stats('المكالمات','Calls',logs.length,'عينة بيانات تجريبية','Sample records','phone')}${stats('نسبة الرد','Answer rate',Math.round(answered/logs.length*100)+'%','للعينة المعروضة فقط','For displayed sample only','usage','green')}</div><div class="quick-grid">${[['member','إضافة موظف','Add employee','نظّم فريق المؤسسة','Organize your team','users'],['extension','إضافة تحويلة','Add extension','اربط موظفاً بجهاز اتصال','Assign a telephony account','phone'],['queue','إنشاء طابور','Create queue','رتّب توزيع المكالمات','Configure call distribution','integrations']].map(([act,a,b,sA,sB,ic])=>`<button class="quick-action" data-action="${act}"><span>${icon(ic)}</span><div><h3>${tx(a,b)}</h3><p>${tx(sA,sB)}</p></div>${icon('arrow')}</button>`).join('')}</div><div class="dashboard-body"><section class="card">${cardHead('نشاط المكالمات','Call activity','آخر 7 أيام · عينة تجريبية','Last 7 days · sample data','<span class="tag">05 — 11 / 10</span>')}${callChart(logs)}</section><section class="current-plan"><small>YOUR SUBSCRIPTION</small><h2>${tx('باقة أعمال','Business plan')}</h2>${badge('active')}<dl>${info('نهاية الفترة','Period end','01/11/2026')}${info('حدود الاستخدام','Usage limits',tx('لم تُعتمد بعد','Not approved yet'))}${info('خدمات الاتصال','Telephony services',tx('غير مجهّزة','Not provisioned'))}</dl>${btn('تفاصيل الاشتراك','Subscription details','go','subscription')}</section></div><div class="dashboard-body"><section class="card">${cardHead('آخر المكالمات','Recent calls','بيانات تجريبية','Sample data',`<button class="text-btn" data-page="calls">${tx('عرض الكل','View all')}${icon('arrow')}</button>`)}${callsTable(logs.slice(0,4),true)}</section><section class="card">${cardHead('طوابير مؤسستك','Organization queues','الإعدادات مسودات غير مفعّلة','Drafts, not provisioned')}<div class="queue-list">${queues.map(queue=>`<div class="queue-item"><div><h3>${esc(nameOf(queue))}</h3><p>${queue.members.length} ${tx('موظفين مسندين','assigned employees')} · ${esc(queue.number)}</p></div>${badge('draft')}</div>`).join('')}</div><div class="detail-actions">${btn('إدارة الطوابير','Manage queues','go','queues')}</div></section></div>`}
function callChart(cs){const days=Array.from({length:7},(_,i)=>'2026-10-'+String(i+5).padStart(2,'0'));const max=Math.max(1,...days.map(d=>cs.filter(c=>c.date===d).length));return `<div class="chart-wrap"><svg class="chart" viewBox="0 0 600 170" role="img" aria-label="${tx('عدد المكالمات حسب اليوم','Call counts by day')}"><path d="M25 25H580M25 65H580M25 105H580M25 145H580" stroke="#edf1f6"/>${days.map((d,i)=>{const total=cs.filter(c=>c.date===d).length,answered=cs.filter(c=>c.date===d&&c.status==='answered').length;return `<rect x="${45+i*77}" y="${145-total/max*104}" width="18" height="${total/max*104}" rx="3" fill="#101D35"/><rect x="${67+i*77}" y="${145-answered/max*104}" width="18" height="${answered/max*104}" rx="3" fill="#F7B955"/><text x="${65+i*77}" y="165" text-anchor="middle">${d.slice(-2)}</text>`}).join('')}</svg><div class="legend"><span><i class="navy"></i>${tx('كل المكالمات','All calls')}</span><span><i></i>${tx('تم الرد','Answered')}</span></div></div>`}
function memberRows(){return members.filter(m=>(filter==='all'||m.status===filter)&&[m.name,m.en,m.username,m.email].some(v=>v.toLowerCase().includes(q.toLowerCase()))).map(m=>`<tr><td><div class="company-cell"><span class="company-avatar">${esc(nameOf(m).slice(-2))}</span><div><strong>${esc(nameOf(m))}</strong><small>${esc(m.email)}</small></div></div></td><td><span class="number">${esc(m.username)}</span></td><td>${tx(...roles[m.role])}</td><td>${esc(deptName(m.dept))}</td><td>${extensions.find(x=>x.user===m.id)?.number||'—'}</td><td>${badge(m.status)}</td><td><div class="table-actions"><button class="row-link" data-action="member" data-id="${m.id}">${tx('تعديل','Edit')}</button><button class="row-link" data-action="memberStatus" data-id="${m.id}" ${m.id===1?'disabled':''}>${m.status==='active'?tx('إيقاف','Disable'):tx('تفعيل','Enable')}</button></div></td></tr>`)}
function searchUI(){return `<div class="filters"><div class="search">${icon('search')}<input id="search" value="${esc(q)}" placeholder="${tx('بحث عن موظف','Search employees')}" aria-label="${tx('بحث','Search')}"></div><select id="filter" aria-label="${tx('الحالة','Status')}"><option value="all">${tx('جميع الحالات','All statuses')}</option><option value="active" ${filter==='active'?'selected':''}>${tx('فعّال','Active')}</option><option value="disabled" ${filter==='disabled'?'selected':''}>${tx('موقوف','Disabled')}</option></select></div>`}
function team(){return head('الفريق والصلاحيات','Team & permissions','إدارة موظفي المؤسسة والوصول إلى وظائف اللوحة.','Manage organization employees and workspace access.',btn('إضافة موظف','Add employee','member','','primary','plus'))+`<div class="tabs"><button class="tab ${teamTab==='members'?'active':''}" data-team-tab="members">${tx('الموظفون','Employees')}</button><button class="tab ${teamTab==='roles'?'active':''}" data-team-tab="roles">${tx('الأدوار والصلاحيات','Roles & permissions')}</button></div>${teamTab==='members'?`<section class="card">${cardHead('فريق المؤسسة','Organization team','حسابات تجريبية داخل مؤسسة واحدة','Sample accounts within one organization')}${searchUI()}<div id="memberTable">${table(['name','username','role','dept','extension','status',['','']],memberRows())}</div></section>`:`${sectionNote('الأدوار مقترحة للتصميم. عزل بيانات المؤسسة وصلاحيات الموظفين يجب فرضها بالخلفية عند التنفيذ.','Roles are proposed for this design. Organization isolation and employee permissions must be enforced by the backend.')}<section class="card">${cardHead('صلاحيات أدوار المؤسسة','Organization role permissions')}${table(['role',...permissionKeys,['','']],Object.entries(roles).map(([id,pair])=>`<tr><td class="permission-name">${tx(...pair)}</td>${permissionMatrix[id].map(v=>`<td style="color:${v?'var(--green)':'#c8d0dc'}">${v?icon('check'):'—'}</td>`).join('')}<td>${id==='admin'?'<span class="tag">ADMIN</span>':btn('تعديل','Edit','permissions',id)}</td></tr>`))}</section>`}`}
function departmentsPage(){return head('الأقسام','Departments','نظّم الموظفين والطوابير بحسب أقسام المؤسسة.','Organize employees and queues by department.',btn('إضافة قسم','Add department','department','','primary','plus'))+`<section class="card">${cardHead('أقسام المؤسسة','Organization departments')}${table(['name',['الموظفون','Employees'],['التحويلات','Extensions'],['الطوابير','Queues'],['','']],departments.map(d=>`<tr><td><div class="company-cell"><span class="company-avatar">${icon('accounts')}</span><strong>${esc(nameOf(d))}</strong></div></td><td>${members.filter(m=>m.dept===d.id).length}</td><td>${extensions.filter(x=>x.dept===d.id).length}</td><td>${queues.filter(q=>q.dept===d.id).length}</td><td>${btn('تعديل القسم','Edit department','department',d.id)}</td></tr>`))}</section>`}
function extensionsPage(){return head('التحويلات والأجهزة','Extensions & devices','حسابات الاتصال الداخلية وإسنادها إلى الموظفين.','Internal telephony accounts and employee assignments.',btn('إضافة تحويلة','Add extension','extension','','primary','plus'))+sectionNote('الأرقام وإسنادات الأجهزة أمثلة للتصميم. تسجيل SIP غير متحقق حتى ربط Asterisk. لا تُعرض كلمات مرور الاتصال في المعاينة.','Numbers and device assignments are design examples. SIP registration remains unverified until Asterisk is connected. No SIP passwords are shown.')+`<section class="card">${cardHead('التحويلات الداخلية','Internal extensions')}${table(['extension',['الموظف','Employee'],'dept','device','registration',['','']],extensions.map(x=>`<tr><td><span class="number">${esc(x.number)}</span></td><td>${esc(memberName(x.user))}</td><td>${esc(deptName(x.dept))}</td><td>${esc(x.device)}</td><td>${badge('unverified')}</td><td>${btn('إعدادات','Settings','extension',x.number)}</td></tr>`))}</section><section class="card" style="margin-top:22px">${empty('لا توجد حالة جهاز فعلية بعد','No live device status yet','حالة الموظف الإدارية منفصلة عن تسجيل الجهاز على SIP. يظهر آخر اتصال بعد الربط الفعلي.','Employee administrative status is separate from SIP registration. Last-seen data will appear after live integration.','phone')}</section>`}
function queuesPage(){return head('طوابير الاتصال','Call queues','توزيع الاتصالات على الموظفين بحسب القسم والاستراتيجية.','Distribute calls by department and ring strategy.',btn('إنشاء طابور','Create queue','queue','','primary','plus'))+sectionNote('هذه إعدادات مسودة؛ حفظها في المعاينة لا يجهّز طابوراً على خادم الاتصالات.','These are draft settings; saving in preview does not provision a queue on the telephony server.')+`<section class="card">${cardHead('طوابير المؤسسة','Organization queues')}${table(['name','number','dept','members','strategy','status',['','']],queues.map(q=>`<tr><td>${esc(nameOf(q))}</td><td>${esc(q.number)}</td><td>${esc(deptName(q.dept))}</td><td><div class="queue-members">${q.members.map(id=>`<span class="mini-avatar" title="${esc(memberName(id))}">${id}</span>`).join('')}<span style="margin-inline-start:5px">${q.members.length}</span></div></td><td>${strategyName(q.strategy)}</td><td>${badge('draft')}</td><td>${btn('إدارة الطابور','Manage queue','queue',String(q.id))}</td></tr>`))}</section>`}function strategyName(s){return s==='ringall'?tx('رنين الجميع','Ring all'):s==='leastrecent'?tx('الأقل اتصالاً مؤخراً','Least recent'):tx('بالتناوب مع الذاكرة','Round robin with memory')}
function targetName(value){const [type,id]=value.split(':');if(type==='queue'){const q=queues.find(q=>q.id===Number(id));return q?nameOf(q):'—'}return tr('تحويلة ','Extension ')+id}function targetOptions(){return [...queues.map(q=>['queue:'+q.id,nameOf(q)]),...extensions.map(e=>['extension:'+e.number,tr('تحويلة ','Extension ')+e.number])]}function ivrPage(){return head('الرد الآلي IVR','IVR menus','نظّم خيارات الرد وتحويل المتصل إلى الوجهة المناسبة.','Route callers to the right destination through menu options.',btn('إنشاء قائمة','Create menu','ivr','','primary','plus'))+sectionNote('الرسالة الصوتية ومسارات القائمة لا تعمل حتى ربط الخادم وتجهيز ملفات الصوت.','Audio prompts and menu routes remain inactive until the server and audio files are provisioned.')+`<div class="details-grid">${ivrs.map(v=>`<section class="card">${cardHead(nameOf(v),nameOf(v),'', '',badge('draft'))}<div class="routing"><div class="routing-top">${icon('integrations')}<div><strong>${esc(nameOf(v))}</strong><small>${esc(v.number)} · ${tx('رسالة صوتية غير مرفوعة','Audio prompt not uploaded')}</small></div></div><div class="routing-branches">${v.routes.map(r=>`<div class="routing-branch"><span class="digit">${esc(r.key)}</span><span class="target">${esc(targetName(r.target))}</span></div>`).join('')}</div><p class="flow-note">${tx('المهلة','Timeout')}: ${v.timeout}s · ${tx('سلوك عدم الاختيار يحتاج إعداداً لاحقاً','No-input behavior needs later configuration')}</p></div><div class="detail-actions">${btn('تعديل القائمة','Edit menu','ivr',String(v.id))}</div></section>`).join('')}</div>`}
function numbersPage(){return head('الأرقام ومسارات الاتصال','Numbers & routing','عرض أرقام المؤسسة وربطها بمسارات الرد.','View organization numbers and their entry routes.',btn('طلب رقم أو ربط','Request number or connection','requestNumber','','primary','plus'))+`<section class="card">${empty('لا توجد أرقام خارجية مربوطة','No external numbers connected','يمكن للمؤسسة طلب ربط رقم. توفير الرقم أو SIP Trunk وتجهيزه يتم عبر إدارة VODNOX ومزود الاتصال.','Your organization can request a number connection. Number or SIP trunk provisioning is handled by VODNOX and the carrier.','phone')}</section><div class="details-grid" style="margin-top:22px"><section class="card">${cardHead('مسار استقبال مقترح','Proposed inbound route')}<dl class="detail-list">${info('رقم المؤسسة','Organization number','—')}${info('الوجهة المقترحة','Proposed destination',esc(org.entry?(org.entry.startsWith('ivr:')?nameOf(ivrs.find(v=>v.id===Number(org.entry.split(':')[1]))||ivrs[0]):targetName(org.entry)):nameOf(ivrs[0])))}${info('ساعات العمل','Business hours',`<span class="number">${esc(org.hours)}</span>`)}${info('خارج أوقات العمل','After hours',org.afterHours==='announcement'?tx('رسالة إغلاق','Closed announcement'):tx('بريد صوتي','Voicemail'))}${info('الحالة','Status',badge('draft'))}</dl><div class="detail-actions">${btn('إعداد مسار مسودة','Configure draft route','routing')}</div></section><section class="card">${cardHead('طلبات المؤسسة','Organization requests')}<div class="settings-body">${requests.filter(r=>r.type==='number').map(r=>`<div class="detail-line"><span>${esc(r.note)}</span>${badge('pending')}</div>`).join('')||`<p class="help-note">${tx('لا توجد طلبات في المعاينة','No preview requests yet')}</p>`}</div></section></div>`}
function filteredCalls(){return logs.filter(c=>(filter==='all'||c.status===filter)&&(deptFilter==='all'||c.dept===deptFilter)&&(!from||c.date>=from)&&(!to||c.date<=to))}function callsTable(cs,compact=false){return table(compact?['date','source','target','status']:['date','source','target','dept','duration','status',['','']],cs.map(c=>`<tr><td><span class="number">${date(c.date)}</span><small class="call-note" style="display:block">${c.time}</small></td><td><span class="number">${esc(c.source)}</span></td><td><span class="number">${esc(c.target)}</span></td>${compact?'':`<td>${esc(deptName(c.dept))}</td><td><span class="number">${duration(c.duration)}</span></td>`}<td>${badge(c.status)}</td>${compact?'':`<td><button class="row-link" data-action="callDetail" data-id="${c.id}">${tx('التفاصيل','Details')}</button></td>`}</tr>`))}
function rangeUI(){return `<div class="filters range-filters"><input type="date" id="from" value="${from}" aria-label="${tx('من تاريخ','From date')}"><input type="date" id="to" value="${to}" aria-label="${tx('إلى تاريخ','To date')}"><select id="filter" aria-label="${tx('حالة المكالمة','Call status')}"><option value="all">${tx('كل الحالات','All statuses')}</option><option value="answered" ${filter==='answered'?'selected':''}>${tx('تم الرد','Answered')}</option><option value="missed" ${filter==='missed'?'selected':''}>${tx('لم يتم الرد','Unanswered')}</option></select><select id="deptFilter" aria-label="${tx('القسم','Department')}"><option value="all">${tx('كل الأقسام','All departments')}</option>${departments.map(d=>`<option value="${d.id}" ${deptFilter===d.id?'selected':''}>${esc(nameOf(d))}</option>`).join('')}</select></div>`}
function callsPage(){return head('سجل المكالمات','Call history','تتبّع مكالمات مؤسستك وأطرافها ونتائجها.','Review organization calls, participants and outcomes.',btn('تصدير السجل','Export history','exportCalls','','secondary','download'))+`<div class="pill-strip"><span class="tag">${tx('عينة مكالمات داخلية','Internal call sample')}</span><span class="tag">VX-1001</span></div><section class="card">${cardHead('مكالمات المؤسسة','Organization calls','بيانات تجريبية، وليست سجلاً فعلياً','Sample data, not a live call log')}${rangeUI()}<div id="callResults">${callsTable(filteredCalls())}</div></section>`}
function recordingsPage(){return head('التسجيلات','Recordings','صلاحيات الوصول وسياسة التسجيل والاحتفاظ الخاصة بالمؤسسة.','Organization recording permissions and retention policy.',btn('سياسة التسجيل','Recording policy','recordPolicy','','secondary','settings'))+`<section class="card">${empty('لا توجد تسجيلات فعلية','No actual recordings','سيتم عرض التسجيلات بعد ربط Asterisk وتفعيل سياسة التسجيل. لا توجد ملفات صوتية أو روابط تنزيل في هذه المعاينة.','Recordings will appear after Asterisk integration and recording-policy activation. No audio files or download links exist in this preview.','record')}</section><div class="details-grid" style="margin-top:22px"><section class="card">${cardHead('سياسة المؤسسة','Organization policy')}<dl class="detail-list">${info('إعداد التسجيل','Recording preference',org.record?tx('مطلوب كتجهيز مسودة','Requested as draft'):tx('غير مفعّل','Not enabled'))}${info('مدة الاحتفاظ','Retention period',org.retention?esc(org.retention)+' '+tx('يوم','days'):tx('لم تُحدد','Not set'))}${info('الوصول','Access',tx('حسب صلاحيات الدور','Per role permissions'))}${info('مساحة التخزين','Storage usage',tx('غير متاحة','Unavailable'))}</dl></section><section class="card">${cardHead('حماية البيانات','Data protection')}<div class="settings-body"><p class="help-note">${tx('حذف التسجيلات وتنزيلها والاستماع إليها يحتاج صلاحيات مستقلة، وتُسجّل العمليات في سجل المراجعة عند التنفيذ الفعلي.','Deleting, downloading and playing recordings require distinct permissions and must be audited in the real implementation.')}</p></div></section></div>`}
function reportSummary(cs){const answered=cs.filter(c=>c.status==='answered'),total=answered.reduce((s,c)=>s+c.duration,0);return `<div class="stats">${stats('المكالمات','Calls',cs.length,'حسب الفلاتر','For selected filters','phone')}${stats('تم الرد','Answered',answered.length,'عينة تجريبية','Sample records','check','green')}${stats('لم يتم الرد','Unanswered',cs.length-answered.length,'عينة تجريبية','Sample records','clock','gold')}${stats('متوسط مدة الحديث','Average talk time',duration(answered.length?Math.round(total/answered.length):0),'للمكالمات المجابة','Answered calls only','usage')}</div><div class="dashboard-body"><section class="card">${cardHead('نشاط المكالمات','Call activity')}${callChart(cs)}</section><section class="card">${cardHead('أداء الأقسام','Department performance')}<div class="queue-list">${departments.map(d=>{const arr=cs.filter(c=>c.dept===d.id);return `<div class="queue-item"><div><h3>${esc(nameOf(d))}</h3><p>${arr.filter(c=>c.status==='answered').length} ${tx('تم الرد','answered')} / ${arr.length} ${tx('مكالمات','calls')}</p></div><div class="metric-inline"><b>${arr.length?Math.round(arr.filter(c=>c.status==='answered').length/arr.length*100):0}%</b><small>${tx('نسبة الرد','Answer rate')}</small></div></div>`}).join('')}</div></section></div><section class="card">${cardHead('نشاط التحويلات','Extension activity')}${table(['extension',['الموظف','Employee'],['مكالمات صادرة داخلية','Internal outgoing calls'],['دقائق حديث','Talk minutes']],extensions.map(x=>{const csx=cs.filter(c=>c.source===x.number);return `<tr><td>${esc(x.number)}</td><td>${esc(memberName(x.user))}</td><td>${csx.length}</td><td>${(csx.reduce((s,c)=>s+c.duration,0)/60).toFixed(1)}</td></tr>`}))}</section>`}
function reportsPage(){return head('تقارير الأداء','Performance reports','تحليل مكالمات المؤسسة والأقسام والتحويلات.','Analyze organization calls, departments and extensions.',btn('تصدير التقرير','Export report','exportCalls','','secondary','download'))+`<section class="card" style="margin-bottom:22px">${cardHead('نطاق التقرير','Report range','الأرقام محسوبة من العينة التجريبية','Metrics calculated from sample records')}${rangeUI()}</section><div id="reportResults">${reportSummary(filteredCalls())}</div>`}
function subscriptionPage(){return head('اشتراك المؤسسة','Organization subscription','متابعة الفترة والفواتير ورفع طلبات التجديد أو تغيير الباقة.','Review subscription periods and invoices, and request renewal or a plan change.',btn('طلب تجديد','Request renewal','subscriptionRequest','renewal','primary','subscriptions'))+sectionNote('التفعيل والتعليق واعتماد الباقات من صلاحية إدارة VODNOX. مسؤول المؤسسة يرفع طلباً فقط. مبالغ الفواتير أمثلة وليست تسعيراً معتمداً.','Activation, suspension and plan approval belong to VODNOX management. Organization admins submit requests only. Invoice amounts are examples, not approved pricing.')+`<div class="settings-layout"><section class="current-plan"><small>ORGANIZATION SUBSCRIPTION</small><h2>${tx('باقة أعمال','Business plan')}</h2>${badge('active')}<dl>${info('دورة الاشتراك','Billing cycle',tx('شهري','Monthly'))}${info('الفترة الحالية','Current period','01/10/2026 — 01/11/2026')}${info('حدود الموظفين والتحويلات','Employee & extension limits',tx('لم تُعتمد','Not approved'))}${info('حد المكالمات المتزامنة','Concurrent call limit',tx('لم يُحدد','Not set'))}${info('حد مساحة التسجيلات','Recording storage limit',tx('لم يُحدد','Not set'))}</dl>${btn('طلب تغيير الباقة','Request plan change','subscriptionRequest','plan')}</section><section class="card">${cardHead('طلبات الاشتراك','Subscription requests')}<div class="settings-body">${requests.filter(r=>r.type==='subscription').map(r=>`<div class="detail-line"><span>${esc(r.note)}</span>${badge('pending')}</div>`).join('')||`<p class="help-note">${tx('لا توجد طلبات في هذه المعاينة.','No requests in this preview yet.')}</p>`}</div></section></div><section class="card" style="margin-top:22px">${cardHead('فواتير المؤسسة','Organization invoices','لا يوجد مزود دفع مربوط','No payment provider connected')}${table([['رقم الفاتورة','Invoice ID'],['المبلغ','Amount'],['الاستحقاق','Due date'],'status',['','']],invoices.map(i=>`<tr><td>${esc(i.id)}</td><td><span class="number">${num(i.amount)} ${tx('د.ع','IQD')}</span></td><td><span class="number">${date(i.date)}</span></td><td>${badge(i.status)}${i.proofName?`<small class="file-name" style="display:block;margin-top:7px">${tx('طلب مراجعة','Review requested')}: ${esc(i.proofName)}</small>`:''}</td><td>${i.status==='unpaid'?btn('إثبات دفع','Payment proof','paymentProof',i.id):icon('check')}</td></tr>`))}</section>`}
function settingsPage(){return head('إعدادات المؤسسة','Organization settings','بيانات مؤسستك وساعات العمل وتفضيلات الإشعارات.','Organization profile, business hours and notification preferences.',btn('حفظ التعديلات','Save changes','settingsSave','','primary','check'))+`<div class="settings-layout"><section class="card">${cardHead('ملف المؤسسة','Organization profile')}<form id="settingsForm" class="settings-body"><div class="company-info-head"><span class="company-avatar">A</span><div><h2>${esc(nameOf(org))}</h2><p>VX-1001 / ORGANIZATION</p></div></div><div class="form-grid">${field('اسم المؤسسة','Organization name','name',org.name,'text',true)}${field('اسم المسؤول','Contact name','contact',org.contact)}${field('البريد الإلكتروني','Email','email',org.email,'email',true)}${field('رقم الهاتف','Phone','phone',org.phone,'tel')}${field('المدينة','City','city',org.city)}${field('المنطقة الزمنية','Timezone','timezone',org.timezone)}${select('اللغة الافتراضية','Default language','language',[['ar',tr('العربية','Arabic')],['en',tr('الإنجليزية','English')]],org.language)}${field('ساعات العمل','Business hours','hours',org.hours)}</div></form></section><section class="card">${cardHead('التفضيلات','Preferences')}<div class="settings-body"><div class="toggle-line"><div><b>${tx('إشعارات الاشتراك','Subscription notifications')}</b><p>${tx('تفضيل مسودة، لا يرسل رسائل فعلية','Draft preference; no actual messages sent')}</p></div><button class="switch" role="switch" aria-label="${tx('إشعارات الاشتراك','Subscription notifications')}" aria-checked="${org.notify}" data-action="notify"></button></div><dl>${info('خارج أوقات العمل','After-hours route',tx('يحتاج تجهيزاً فعلياً','Needs actual provisioning'))}${info('بيانات المؤسسة','Organization data',tx('معزولة عند التنفيذ بالخلفية','Isolated by backend implementation'))}</dl><p class="help-note">${tx('لا توجد إعدادات خادم أو مفاتيح AMI أو إدارة شركات أخرى في لوحة المؤسسة.','This workspace does not expose server credentials, AMI keys or other organizations.')}</p></div></section></div>`}
function auditPage(){return head('سجل النشاط','Activity log','مراجعة التغييرات الإدارية داخل المؤسسة.','Review administrative changes within your organization.')+`<section class="card">${cardHead('نشاط المؤسسة','Organization activity','عينة تجريبية','Sample data')}${activities.map(a=>`<div class="audit-item"><span>${icon('audit')}</span><div><h3>${tx(a.ar,a.en)}</h3><small>${tx('مسؤول المؤسسة','Organization admin')} · ${esc(a.date)}</small></div></div>`).join('')}</section>`}
function render(){renderNav();const n=navItems.find(n=>n[0]===page);$('#crumb').textContent=tr(n[1],n[2]);const pages={overview,team,departments:departmentsPage,extensions:extensionsPage,queues:queuesPage,ivr:ivrPage,numbers:numbersPage,calls:callsPage,recordings:recordingsPage,reports:reportsPage,subscription:subscriptionPage,settings:settingsPage,audit:auditPage};$('#content').innerHTML=pages[page]();document.title='VODNOX | '+$('#crumb').textContent;$('#sidebar').classList.remove('open');if(page==='team'&&teamTab==='members'){const update=()=>$('#memberTable').innerHTML=table(['name','username','role','dept','extension','status',['','']],memberRows());$('#search').addEventListener('input',e=>{q=e.target.value;update()});$('#filter').addEventListener('change',e=>{filter=e.target.value;update()})}if(page==='calls'||page==='reports'){['from','to','filter','deptFilter'].forEach(id=>$('#'+id).addEventListener('change',e=>{if(id==='from')from=e.target.value;if(id==='to')to=e.target.value;if(id==='filter')filter=e.target.value;if(id==='deptFilter')deptFilter=e.target.value;if(from&&to&&from>to)toast('تاريخ البداية بعد النهاية؛ عدّل الفترة.','Start date follows end date; adjust the range.');if(page==='calls')$('#callResults').innerHTML=callsTable(filteredCalls());else $('#reportResults').innerHTML=reportSummary(filteredCalls())}))}if($('#settingsForm'))$('#settingsForm').addEventListener('submit',e=>{e.preventDefault();saveSettings()})}
function navigate(p){page=p;q='';filter='all';deptFilter='all';history.replaceState(null,'','#'+p);render();window.scrollTo(0,0)}function saveSettings(){const f=$('#settingsForm');if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));Object.assign(org,data,{en:data.name});audit('تعديل إعدادات المؤسسة في المعاينة','Organization settings updated in preview');previewSaved();render()}
function editMember(id){const m=members.find(m=>m.id===Number(id));const body=`<div class="form-grid">${field('اسم الموظف','Employee name','name',m?.name||'','text',true)}${field('اسم المستخدم','Username','username',m?.username||'','text',true)}${field('البريد الإلكتروني','Email','email',m?.email||'','email',true)}${select('القسم','Department','dept',departments.map(d=>[d.id,nameOf(d)]),m?.dept||departments[0].id)}${select('الدور','Role','role',Object.entries(roles).map(([id,p])=>[id,tr(...p)]),m?.role||'agent')}</div><p class="field-help">${tx('لا تُدخل كلمات مرور فعلية. إنشاء بيانات المصادقة وتفعيل الحساب ينفّذ بالخلفية لاحقاً.','Do not enter real passwords. Credentials and actual account activation will be handled by the backend later.')}</p>`;modal(m?'تعديل الموظف':'إضافة موظف',m?'Edit employee':'Add employee',body,'حفظ الموظف','Save employee',data=>{if(members.some(x=>x.id!==m?.id&&x.username===data.username)){toast('اسم المستخدم مستخدم داخل المؤسسة.','Username already exists in this organization.');return false}if(m?.id===1&&data.role!=='admin'){toast('يجب الحفاظ على مسؤول المؤسسة في هذه المعاينة.','Keep the organization admin role in this preview.');return false}if(m){Object.assign(m,{...data,en:data.name});extensions.filter(x=>x.user===m.id).forEach(x=>x.dept=data.dept)}else members.push({id:Math.max(...members.map(m=>m.id))+1,...data,en:data.name,status:'active'});audit('حفظ حساب موظف تجريبي','Sample employee account saved');previewSaved();return true})}
function editExtension(id){const x=extensions.find(x=>x.number===id);modal('إعداد التحويلة','Extension settings',sectionNote('الإعداد مسودة فقط؛ لن يتم إنشاء حساب SIP فعلي أو توليد كلمة مرور اتصال.','Draft only; no actual SIP account or SIP password will be created.')+`<div class="form-grid">${field('رقم التحويلة','Extension number','number',x?.number||'','text',true)}${select('الموظف','Employee','user',members.filter(m=>m.status==='active'||m.id===x?.user).map(m=>[m.id,nameOf(m)]),x?.user||members[0].id)}${select('القسم','Department','dept',departments.map(d=>[d.id,nameOf(d)]),x?.dept||departments[0].id)}${select('نوع الجهاز','Device type','device',[['Softphone','Softphone'],['Mobile','Mobile'],['IP Phone','IP Phone']],x?.device||'Softphone')}</div>`,'حفظ المسودة','Save draft',data=>{if(!/^\d{3,6}$/.test(data.number)||extensions.some(e=>e!==x&&e.number===data.number)||queues.some(q=>q.number===data.number)||ivrs.some(v=>v.number===data.number)){toast('اختر رقماً داخلياً فريداً من 3 إلى 6 أرقام.','Choose a unique internal number of 3 to 6 digits.');return false}if(extensions.some(e=>e!==x&&e.user===Number(data.user))){toast('للموظف تحويلة مسندة بالفعل في هذه المعاينة.','Employee already has an assigned extension in this preview.');return false}const old=x?.number;if(x)Object.assign(x,{...data,user:Number(data.user)});else extensions.push({...data,user:Number(data.user)});if(old&&old!==data.number)ivrs.forEach(v=>v.routes.forEach(r=>{if(r.target==='extension:'+old)r.target='extension:'+data.number}));audit('حفظ مسودة تحويلة','Extension draft saved');previewSaved();return true})}
function editQueue(id){const queue=queues.find(q=>q.id===Number(id));modal('إدارة طابور الاتصال','Manage call queue',`<div class="form-grid">${field('اسم الطابور','Queue name','name',queue?.name||'','text',true)}${field('الرقم الداخلي','Internal number','number',queue?.number||'','text',true)}${select('القسم','Department','dept',departments.map(d=>[d.id,nameOf(d)]),queue?.dept||departments[0].id)}${select('استراتيجية التوزيع','Ring strategy','strategy',[['ringall',tr('رنين الجميع','Ring all')],['rrmemory',tr('بالتناوب مع الذاكرة','Round robin with memory')],['leastrecent',tr('الأقل اتصالاً مؤخراً','Least recent')]],queue?.strategy||'rrmemory')}${field('مهلة الرد بالثواني','Ring timeout (seconds)','timeout',queue?.timeout||30,'number',true)}</div><p class="field-help">${tx('الموظفون المسندون','Assigned employees')}</p><div class="checkbox-list">${members.filter(m=>m.status==='active').map(m=>`<label><input type="checkbox" name="member${m.id}" ${queue?.members.includes(m.id)?'checked':''}>${esc(nameOf(m))}</label>`).join('')}</div>`,'حفظ المسودة','Save draft',data=>{if(!/^\d{3,6}$/.test(data.number)||queues.some(q=>q!==queue&&q.number===data.number)||extensions.some(e=>e.number===data.number)||ivrs.some(v=>v.number===data.number)){toast('الرقم الداخلي غير صالح أو مستخدم.','Internal number is invalid or already used.');return false}const selected=members.filter(m=>data['member'+m.id]==='on').map(m=>m.id);if(!selected.length){toast('اختر موظفاً واحداً على الأقل.','Select at least one employee.');return false}const values={name:data.name,en:data.name,number:data.number,dept:data.dept,strategy:data.strategy,timeout:Number(data.timeout),members:selected};if(queue)Object.assign(queue,values);else queues.push({id:Math.max(...queues.map(q=>q.id))+1,...values});audit('حفظ مسودة طابور اتصال','Call queue draft saved');previewSaved();return true})}
function editIvr(id){const v=ivrs.find(v=>v.id===Number(id));modal('إدارة قائمة الرد الآلي','Manage IVR menu',`<div class="form-grid">${field('اسم القائمة','Menu name','name',v?.name||'','text',true)}${field('الرقم الداخلي','Internal number','number',v?.number||'','text',true)}${field('مهلة الاختيار بالثواني','Input timeout (seconds)','timeout',v?.timeout||10,'number',true)}${['1','2','0'].map(k=>select('عند الضغط على '+k,'When pressing '+k,'key'+k,[['none',tr('بدون مسار','No route')],...targetOptions()],v?.routes.find(r=>r.key===k)?.target||'none')).join('')}</div><p class="field-help">${tx('رفع الرسائل الصوتية وسياسة عدم الرد والتكرار تُجهّز عند التنفيذ الفعلي.','Audio uploads, no-input behavior and retry policies will be implemented during actual provisioning.')}</p>`,'حفظ المسودة','Save draft',data=>{if(!/^\d{3,6}$/.test(data.number)||ivrs.some(x=>x!==v&&x.number===data.number)||queues.some(q=>q.number===data.number)||extensions.some(x=>x.number===data.number)){toast('الرقم الداخلي غير صالح أو مستخدم.','Internal number is invalid or already used.');return false}if(['1','2','0'].every(k=>data['key'+k]==='none')){toast('اختر وجهة واحدة على الأقل.','Choose at least one destination.');return false}const values={name:data.name,en:data.name,number:data.number,timeout:Number(data.timeout),routes:['1','2','0'].filter(k=>data['key'+k]!=='none').map(k=>({key:k,target:data['key'+k]}))};if(v)Object.assign(v,values);else ivrs.push({id:Math.max(...ivrs.map(v=>v.id))+1,...values});audit('حفظ مسودة قائمة IVR','IVR menu draft saved');previewSaved();return true})}
function request(type,id){const subscription=type==='subscription',a=subscription?'طلب اشتراك':'طلب رقم أو ربط',b=subscription?'Subscription request':'Number or connection request';modal(a,b,sectionNote('يُحفظ الطلب داخل هذه المعاينة فقط؛ لا يُرسل إلى إدارة المنصة أو أي مزود.','Request remains in this preview only; it is not sent to platform management or any provider.')+`<div class="form-grid">${subscription?select('نوع الطلب','Request type','requestType',[['renewal',tr('تجديد','Renewal')],['plan',tr('تغيير الباقة','Plan change')]],id||'renewal'):field('رقم مطلوب أو موجود إن توفر','Requested or existing number, if any','number','','tel')}<div class="form-field full"><label for="f-note">${tx('تفاصيل الطلب','Request details')}</label><textarea name="note" id="f-note" required></textarea></div></div>`,'حفظ الطلب التجريبي','Save sample request',data=>{requests.unshift({type,note:data.note,requestType:data.requestType||'number'});audit('إنشاء طلب تجريبي للمؤسسة','Organization preview request created');previewSaved();return true})}
function exportCalls(){const cs=filteredCalls();const rows=[['Demo record','Date','Source','Destination','Department','Status','Duration seconds'],...cs.map(c=>[c.id,c.date,c.source,c.target,deptName(c.dept),c.status,c.duration])];const cell=v=>{let s=String(v);if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='vodnox-organization-demo-calls.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم تصدير العينة حسب الفلاتر.','Sample exported using selected filters.')}
function action(n,id,el){if(n==='go')return navigate(id);if(n==='member')return editMember(id);if(n==='memberStatus'){const m=members.find(m=>m.id===Number(id));if(m.id===1)return;return modal('تغيير حالة الموظف','Change employee status',sectionNote('تغيير الحالة الإدارية لا يقطع مكالمة أو يغيّر تسجيل SIP في هذه المعاينة.','Administrative state changes do not terminate a call or change SIP registration in this preview.')+`<p>${esc(nameOf(m))}</p>`,'تأكيد','Confirm',()=>{m.status=m.status==='active'?'disabled':'active';audit('تغيير حالة موظف في المعاينة','Employee state changed in preview');previewSaved();return true})}if(n==='department'){const d=departments.find(d=>d.id===id);return modal('إعداد القسم','Department settings',field('اسم القسم','Department name','name',d?.name||'','text',true),'حفظ','Save',data=>{if(d)Object.assign(d,{name:data.name,en:data.name});else departments.push({id:'dept'+Date.now(),name:data.name,en:data.name});audit('حفظ قسم تجريبي','Sample department saved');previewSaved();return true})}if(n==='extension')return editExtension(id);if(n==='queue')return editQueue(id);if(n==='ivr')return editIvr(id);if(n==='requestNumber')return request('number');if(n==='subscriptionRequest')return request('subscription',id);if(n==='permissions')return modal('صلاحيات الدور','Role permissions',`<div class="section-note">${tx(...roles[id])}</div><div class="checkbox-list">${permissionKeys.map(([a,b],i)=>`<label><input type="checkbox" name="p${i}" ${permissionMatrix[id][i]?'checked':''}>${tx(a,b)}</label>`).join('')}</div>`,'حفظ المسودة','Save draft',data=>{permissionMatrix[id]=permissionKeys.map((_,i)=>data['p'+i]==='on');audit('تعديل مسودة صلاحيات الدور','Draft role permissions updated');previewSaved();return true});if(n==='callDetail'){const c=logs.find(c=>c.id===id);return modal('تفاصيل مكالمة تجريبية','Sample call details',`<dl>${info('معرّف المكالمة','Call ID',c.id)}${info('التاريخ','Date',date(c.date)+' · '+c.time)}${info('من','From',c.source)}${info('إلى','To',c.target)}${info('القسم','Department',esc(deptName(c.dept)))}${info('مدة الحديث','Talk duration',duration(c.duration))}${info('الحالة','Status',badge(c.status))}${info('التسجيل','Recording',tx('لا يوجد ملف فعلي','No actual file'))}${info('نوع الاتصال','Call type',tx('داخلية تجريبية','Internal sample'))}</dl>`,'إغلاق','Close',()=>true)}if(n==='recordPolicy')return modal('سياسة التسجيل','Recording policy',sectionNote('هذه تفضيلات مسودة ولا تُفعّل التسجيل. سياسة الموافقة والاحتفاظ تطبّق عند الربط الفعلي.','Draft preferences do not enable recording. Consent and retention policies must be enforced during actual integration.')+`<div class="checkbox-line"><input id="f-record" name="record" type="checkbox" ${org.record?'checked':''}><label for="f-record">${tx('طلب تفعيل التسجيل','Request recording activation')}</label></div>${field('مدة الاحتفاظ بالأيام','Retention period (days)','retention',org.retention,'number')}`,'حفظ التفضيل','Save preference',data=>{org.record=data.record==='on';org.retention=data.retention;audit('تعديل مسودة سياسة التسجيل','Recording policy draft updated');previewSaved();return true});if(n==='routing')return modal('مسار الاتصال المقترح','Proposed call route',`<div class="form-grid">${select('وجهة الدخول','Entry destination','destination',[...ivrs.map(v=>['ivr:'+v.id,nameOf(v)]),...targetOptions()],org.entry||'ivr:1')}${select('خارج أوقات العمل','After hours','afterHours',[['voicemail',tr('بريد صوتي','Voicemail')],['announcement',tr('رسالة إغلاق','Closed announcement')]],org.afterHours)}</div>`,'حفظ المسودة','Save draft',data=>{org.entry=data.destination;org.afterHours=data.afterHours;audit('تعديل مسودة مسار الاتصال','Draft call route updated');previewSaved();return true});if(n==='paymentProof')return modal('إثبات دفع تجريبي','Sample payment proof',sectionNote('لا يتم رفع الملف أو تأكيد الدفع في هذه المعاينة. قبول الدفعة من صلاحية إدارة المنصة.','No file is uploaded and no payment is confirmed in this preview. Payment acceptance belongs to platform management.')+`<p class="help-note">${esc(id)}</p><div class="form-grid">${field('مرجع التحويل','Transfer reference','reference','','text',true)}${field('اختيار ملف للمعاينة فقط','Choose a file for preview only','proof','','file',true,true)}</div>`,'تسجيل طلب مراجعة','Record review request',data=>{const invoice=invoices.find(i=>i.id===id);invoice.proofName=data.proof?.name||'';audit('إضافة طلب مراجعة إثبات دفع تجريبي','Sample payment proof review requested');toast('حُفظ اسم الملف للمعاينة. لم يُرفع الملف ولم يتغير وضع الفاتورة.','Filename saved in preview. File not uploaded; invoice status unchanged.');return true});if(n==='exportCalls')return exportCalls();if(n==='settingsSave')return saveSettings();if(n==='notify'){org.notify=!org.notify;el.setAttribute('aria-checked',String(org.notify));return previewSaved()}}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p)return navigate(p.dataset.page);const tab=e.target.closest('[data-team-tab]');if(tab){teamTab=tab.dataset.teamTab;filter='all';q='';render();return}const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b.dataset.action,b.dataset.id||'',b)}});$('#modalForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(modalHandler(data)!==false){$('#modal').close();render()}});$('#cancelModal').onclick=$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#language').onclick=()=>{lang=lang==='ar'?'en':'ar';document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';render()};$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#notifications').onclick=()=>modal('تنبيهات المؤسسة','Organization notifications',`<div class="detail-line"><span>${tx('الاشتراك ينتهي بتاريخ','Subscription ends on')} 01/11/2026</span>${badge('active')}</div><div class="detail-line"><span>${tx('خادم الاتصال غير مربوط','Telephony server not connected')}</span>${badge('unconnected')}</div><div class="detail-line"><span>${tx('مسودات الاتصال تنتظر التجهيز','Telephony drafts await provisioning')}</span>${badge('draft')}</div>`,'إغلاق','Close',()=>true);document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar').classList.remove('open')});const initial=location.hash.slice(1);if(navItems.some(n=>n[0]===initial))page=initial;render();

window.addEventListener('vodnox-crm-change',renderNav);

window.addEventListener('vodnox-forms-change',renderNav);
